$l2Quiz=[ordered]@{course='JOURNALISM';unit=4;lesson=2;quizTitle='Journalism Unit 4 Lesson 2 Quiz';lessonReference='Unit 04 Lesson 02';giftFile='JOUR_U04_L02_Quiz.gift';questionCount=25;standards=@('MLA.JOUR.MED.02','MLA.JOUR.REP.02','MLA.JOUR.MED.01')} | ConvertTo-Json -Depth 5
WriteText (Join-Path $l2 'quiz.json') $l2Quiz

$std1=@('MLA.JOUR.MED.01','MLA.JOUR.NEWS.03','MLA.JOUR.MED.03')
$std2=@('MLA.JOUR.MED.02','MLA.JOUR.REP.02','MLA.JOUR.MED.01')
$prompts1=@('Which feature best supports audience navigation?','Which explanation describes the sidebar function?','Which structure description is most accurate?','Which choice explains the caption purpose?','Which answer connects feature to audience use?')
$prompts2=@('Which statement is the central idea?','Which detail best supports the central idea?','Which explanation connects evidence to the message?','Which detail is strongest support?','Which answer distinguishes topic from central idea?')
$correct1='Explain how the media feature or structure helps readers understand, locate, remember, or use information.'
$correct2='State the central idea accurately and explain how relevant source details develop that main message.'
$wrong1=@('Say the feature matters because it makes the page look colorful.','Ignore the feature and summarize only the article topic.','Add a new feature that is not described in the source.')
$wrong2=@('State only the broad topic without the message.','Choose a true detail that does not develop the central idea.','Add unsupported evidence that is not in the media text.')
WriteText (Join-Path $l1 'JOUR_U04_L01_GuidedPractice.gift') (MakeGift 'JOUR_U04_L01_GP' 5 $std1 $prompts1 @('B','D','A','C','B') $source1Gift $correct1 $wrong1)
WriteText (Join-Path $l1 'JOUR_U04_L01_Quiz.gift') (MakeGift 'JOUR_U04_L01_Q' 25 $std1 $prompts1 @('C','A','D','B','A','C','B','D') $source1Gift $correct1 $wrong1)
WriteText (Join-Path $l2 'JOUR_U04_L02_GuidedPractice.gift') (MakeGift 'JOUR_U04_L02_GP' 5 $std2 $prompts2 @('D','B','A','C','D') $source2Gift $correct2 $wrong2)
WriteText (Join-Path $l2 'JOUR_U04_L02_Quiz.gift') (MakeGift 'JOUR_U04_L02_Q' 25 $std2 $prompts2 @('A','C','B','D','B','A','D','C') $source2Gift $correct2 $wrong2)
